package com.obysoft.faithOS.controller;
import java.util.List;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import com.obysoft.faithOS.dto.*;import com.obysoft.faithOS.service.ContributionService;import jakarta.validation.Valid;
@RestController @RequestMapping("/api/contributions") @PreAuthorize("hasAnyRole('SUPER_ADMIN','CHURCH_ADMIN')")
public class ContributionController{private final ContributionService service;public ContributionController(ContributionService service){this.service=service;}@GetMapping public List<ContributionResponse> all(){return service.all();}@PostMapping public ResponseEntity<ContributionResponse> create(@Valid @RequestBody ContributionRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));}@PutMapping("/{id}") public ContributionResponse update(@PathVariable Long id,@Valid @RequestBody ContributionRequest r){return service.update(id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){service.delete(id);}}
